use std::borrow::Cow;

use gpui_kit::assets::Assets;
use gpui_kit::{AssetSource, Result, SharedString};
use loadout_core::model::AppIcon;

// Icons beyond GPUI Kit's default set.
gpui_kit::assets::icon_assets!(
    ExtraIcons,
    [
        Circle,
        Sparkles,
        Pin,
        ShieldAlert,
        Layers,
        Command,
        Clock,
        FolderPlus
    ]
);

/// App icon variants, regenerated by `packaging/icon/make-variants.sh`.
const APP_ICONS: &[(&str, &[u8])] = &[
    (
        "app-icon/default.png",
        include_bytes!("../assets/app-icon/default.png"),
    ),
    (
        "app-icon/twilight.png",
        include_bytes!("../assets/app-icon/twilight.png"),
    ),
    (
        "app-icon/graphite.png",
        include_bytes!("../assets/app-icon/graphite.png"),
    ),
    (
        "app-icon/default-dock.png",
        include_bytes!("../assets/app-icon/default-dock.png"),
    ),
    (
        "app-icon/twilight-dock.png",
        include_bytes!("../assets/app-icon/twilight-dock.png"),
    ),
    (
        "app-icon/graphite-dock.png",
        include_bytes!("../assets/app-icon/graphite-dock.png"),
    ),
];

/// The in-app tile for `icon`, as an asset path for `img()`.
pub fn app_icon_path(icon: AppIcon) -> SharedString {
    format!("app-icon/{}.png", icon_name(icon)).into()
}

/// The padded Dock image for `icon`.
pub fn dock_icon_bytes(icon: AppIcon) -> &'static [u8] {
    let path = format!("app-icon/{}-dock.png", icon_name(icon));
    APP_ICONS
        .iter()
        .find(|(p, _)| *p == path)
        .map_or(&[], |(_, bytes)| bytes)
}

fn icon_name(icon: AppIcon) -> &'static str {
    match icon {
        AppIcon::Default => "default",
        AppIcon::Twilight => "twilight",
        AppIcon::Graphite => "graphite",
    }
}

pub struct AppAssets;

impl AssetSource for AppAssets {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        if let Some((_, bytes)) = APP_ICONS.iter().find(|(p, _)| *p == path) {
            return Ok(Some(Cow::Borrowed(bytes)));
        }
        if let Some(bytes) = ExtraIcons.load(path)? {
            return Ok(Some(bytes));
        }
        Assets.load(path)
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        let mut paths = Assets.list(path)?;
        paths.extend(ExtraIcons.list(path)?);
        paths.extend(
            APP_ICONS
                .iter()
                .filter(|(p, _)| p.starts_with(path))
                .map(|(p, _)| SharedString::from(*p)),
        );
        paths.sort();
        paths.dedup();
        Ok(paths)
    }
}
